function IdolLive3D_FreeCameraSpatialParams:__init( yaw_, pitch_, zoom_ )
    if      type(yaw_) ~= "number"
        or  type(pitch_) ~= "number"    or  (pitch_ < 0)    or  (pitch_ > 1)
        or  type(zoom_) ~= "number"     or  (zoom_  < 0)    or  (zoom_  > 1)
    then  
        printError( "参数异常, yaw: " .. tostring(yaw_) .. ", pitch: " .. tostring(pitch_) .. ", zoom: " .. tostring(zoom_)  )
    end
    ---
    --self.yaw    = Mathf.Clamp( checkNumber(yaw_), 0.0, 360.0  ) -- 相机在角色的哪个方位, [0,360], 在角色正前方为 0/360, 在角色右侧为 90, 后方为 180, 左侧为 270
    self.yaw    = checkNumber(yaw_)                             -- 相机在角色的哪个方位, [0,360], 在角色正前方为 0/360, 在角色右侧为 90, 后方为 180, 左侧为 270
    self.pitch  = Mathf.Clamp01( checkNumber(pitch_) )          -- pitch t 值, [0,1] 表示相机在 pitch 轨道上的位置; 通常 上端为 0, 下端为 1
    self.zoom   = Mathf.Clamp01( checkNumber(zoom_) )           -- zoom t 值, [0,1] 近端为 0, 远端为 1
end




